    )
    case navigate(nav: Nav
    )
    case setFilter(filter: Filter
    )
    case setTab(tab: Tab
    )
    case search(query: String
    )
    case dismissError
    /**
     * Closes one notice banner, by its text.
     */
    case dismissNotice(text: String
    )
    case select(target: Target
    )
    case toggleTeam(id: String
    )
    case loadChannels(id: String
    )
    case channelMembers
