public enum FileAction: Equatable, Hashable {
    
    /**
     * Open in the browser.
     */
    case `open`(key: String
    )
    case copyLink(key: String
    )
    /**
     * Download to `path`, chosen by the user.
     */
    case download(key: String, path: String
    )
    /**
     * Download to a temporary folder and show it in Quick Look.
     */
    case preview(key: String
    )
    case cancel(key: String
    )
    /**
     * Upload local files as attachments of the current draft.
     */
    case attach(paths: [String]
    )
    /**
     * An image pasted in the composer, as PNG: it goes inline in the message, as in Teams, not to OneDrive.
     * `id` is the one its placeholder in the draft carries (`ComposerFormat::image`); `width` and `height` are
     * its size on screen, in points.
     */
    case pasteImage(id: String, png: Data, width: UInt32, height: UInt32
    )
    case removeAttachment(id: String
    )
    case sharedFilter(filter: SharedFilter
    )
    /**
     * Filters the 'Partagé' list by name, sender or link; empty shows all.
     */
    case sharedSearch(query: String
    )
    case refreshShared
    case browse(place: BrowserPlace
    )
    case openFolder(key: String
    )
    /**
     * Go back to the crumb at `index` (0 = root).
     */
    case crumb(index: UInt32
    )
    case newFolder(name: String
    )
    case rename(key: String, name: String
    )
    case delete(key: String
    )
    /**
     * Folder colour, 0 (default yellow) to 15.
     */
    case setColor(key: String, color: UInt8
    )
    /**
     * Upload local files into the folder shown by the browser.
     */
    case uploadHere(paths: [String]
    )
    case refreshBrowser
    /**
     * Search the place shown (the whole OneDrive, or the channel's folder); empty ends it.
     */
    case searchFiles(query: String
    )





}

