    )
    case setToggle(toggle: NotificationToggle, on: Bool
    )
    case setSound(urgent: Bool, sound: NotificationSound
    )
    case setEmailDelay(delay: EmailDelay
    )
    case setMeetingChats(choice: MeetingChats
    )
    case pause(minutes: UInt32
    )
    /**
     * Until 8:00 tomorrow, local time.
     */
    case pauseUntilTomorrow
    case pauseUntil(epochMs: Int64
    )
    case resume
    case permissionChanged(permission: NotificationPermission
    )
    /**
     * A banner was clicked.
     */
    case `open`(conversationId: String, replyChainId: String?
    )
    /**
     * Quick reply typed in a banner.
     */
    case reply(conversationId: String, replyChainId: String?, text: String
    )
    case markRead(conversationId: String
    )
    case setChatMuted(conversationId: String, muted: Bool
    )
    case editChat(conversationId: String
    )
    case editChannel(team: String, channel: String
    )
    case closeEditor
    /**
     * Applies to the chat of the open editor.
     */
    case setChatSettings(muted: Bool, everyoneMentions: Bool, desktop: ChatDesktop
    )
    /**
     * Applies to the channel of the open editor.
     */
    case setChannelSettings(allNewPosts: ChannelChoice, includeReplies: Bool, channelMentions: ChannelChoice, followAllThreads: Bool
    )
    /**
     * "Turn off" from a channel menu.
     */
    case muteChannel(team: String, channel: String
    )
    /**
     * Follow or unfollow a post of the open channel.
     */
    case setPostFollow(post: String, follow: Bool
    )
    case markAllActivityRead
    case muteDuringThisCall(muted: Bool
    )
    /**
     * Send and see read receipts (`readReceiptsEnabled`).
     */
    case setReadReceipts(on: Bool
    )
    /**
     * Shows a sample banner, whatever the settings.
     */
    case sendTest





}

