private enum InitializationResult {
    case ok
    case contractVersionMismatch
    case apiChecksumMismatch
}
// Use a global variable to perform the versioning checks. Swift ensures that
// the code inside is only computed once.
private let initializationResult: InitializationResult = {
    // Get the bindings contract version from our ComponentInterface
    let bindings_contract_version = 30
    // Get the scaffolding contract version by calling the into the dylib
    let scaffolding_contract_version = ffi_teams_core_uniffi_contract_version()
    if bindings_contract_version != scaffolding_contract_version {
        return InitializationResult.contractVersionMismatch
    }
    if (uniffi_teams_core_checksum_func_app_version() != 31466) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_teams_core_checksum_func_clear_picture_cache() != 63643) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_teams_core_checksum_func_composer_emojis() != 60167) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_teams_core_checksum_func_demo_available() != 43320) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_teams_core_checksum_func_is_login_allowed() != 2456) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_teams_core_checksum_func_is_login_callback() != 46075) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_teams_core_checksum_func_picture_cache() != 26815) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_teams_core_checksum_func_set_cache_directory() != 12953) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_teams_core_checksum_func_set_language() != 47377) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_teams_core_checksum_func_sticker_categories() != 2627) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_teams_core_checksum_func_translations() != 51693) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_teams_core_checksum_func_rust_memory() != 6749) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_teams_core_checksum_method_corelistener_update() != 56437) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_teams_core_checksum_method_corelistener_effect() != 29884) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_teams_core_checksum_method_oxidecore_send() != 32850) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_teams_core_checksum_method_oxidecore_set_active() != 52625) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_teams_core_checksum_method_oxidecore_take_avatar() != 53920) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_teams_core_checksum_method_oxidecore_take_image() != 7577) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_teams_core_checksum_method_oxidecore_take_voicemail_audio() != 49343) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_teams_core_checksum_constructor_oxidecore_new() != 9344) {
        return InitializationResult.apiChecksumMismatch
    }

    uniffiCallbackInitCoreListener()
    return InitializationResult.ok
